using namespace std;

using ll = long long;
using i128 = __int128_t;

const ll MOD = 998244353LL;
const ll MODD = 1000000007LL;
const int MAX_SIZE = 1000005;
const ll INF = 1000000000000000000LL;

ll power_of_ten[15];
vector<string> digit_groups[7];
vector<ll> processed_values[7][7];
ll cumulative_sums[7][7];

inline ll convert_to_number(const string& str) {
    ll result = 0;
    for (char ch : str) {
        result = result * 10 + (ch - '0');
    }
    return result;
}

inline i128 process_string(const string& prefix, int remaining_length, ll& counter) {
    if (remaining_length == -1) return 0;

    int left_part_length = remaining_length / 2;
    int right_part_length = remaining_length - left_part_length;
    if (remaining_length == 1) {
        left_part_length = 1;
        right_part_length = 0;
    }

    i128 total = (counter - convert_to_number(prefix) + MOD * MOD) % MOD;
    counter++;

    for (const string& left_segment : digit_groups[left_part_length]) {
        string combined = prefix + left_segment;
        total += (-convert_to_number(combined) + counter + MOD * MOD) % MOD;
        counter++;

        if ((int)left_segment.size() == left_part_length) {
            ll value = convert_to_number(combined) % MOD;
            for (int right_size = 1; right_size <= right_part_length; ++right_size) {
                ll constant = (-value * power_of_ten[right_size] + counter + MOD * MOD) % MOD;
                auto& vec = processed_values[right_part_length][right_size];
                int pos = lower_bound(vec.begin(), vec.end(), MOD - constant) - vec.begin();
                total += (i128)vec.size() * constant + cumulative_sums[right_part_length][right_size] - (i128)MOD * (vec.size() - pos);
            }
            counter += digit_groups[right_part_length].size();
        }
    }
    return total;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n;
    cin >> n;
    string num_str = to_string(n);
    int total_digits = num_str.length();

    power_of_ten[0] = 1;
    for (int i = 1; i <= 14; ++i) {
        power_of_ten[i] = power_of_ten[i-1] * 10;
    }

    for (int i = 0; i < MAX_SIZE; ++i) {
        string current = to_string(i);
        string padded = current;
        while ((int)padded.length() <= 6) {
            padded = "0" + padded;
            digit_groups[padded.length()].push_back(padded);
        }
    }

    for (int len = 1; len <= 6; ++len) {
        for (const string& prev : digit_groups[len-1]) {
            digit_groups[len].push_back(prev);
        }
        sort(digit_groups[len].begin(), digit_groups[len].end());

        for (int idx = 0; idx < (int)digit_groups[len].size(); ++idx) {
            ll val = (idx - stoi(digit_groups[len][idx]) + MOD) % MOD;
            processed_values[len][digit_groups[len][idx].length()].push_back(val);
        }

        for (int sz = 1; sz <= len; ++sz) {
            sort(processed_values[len][sz].begin(), processed_values[len][sz].end());
            for (ll v : processed_values[len][sz]) {
                cumulative_sums[len][sz] += v;
            }
        }
    }

    vector<pair<string, int>> query_list;
    string current_string = "";

    for (int i = 0; i < (int)num_str.length(); ++i) {
        for (int digit = 0; digit <= 9; ++digit) {
            if (digit == num_str[i] - '0') continue;
            if (i == 0 && digit == 0) continue;

            current_string += char('0' + digit);
            if (digit <= num_str[i] - '0') {
                query_list.emplace_back(current_string, (int)num_str.length() - i - 1);
            } else {
                query_list.emplace_back(current_string, (int)num_str.length() - i - 2);
            }
            current_string.pop_back();
        }
        current_string += num_str[i];
        query_list.emplace_back(current_string, 0);
    }

    ll counter = 1;
    i128 final_answer = 0;
    sort(query_list.begin(), query_list.end());

    for (const auto& item : query_list) {
        if (num_str[item.first.length() - 1] == item.first.back()) {
            final_answer += (-convert_to_number(item.first) + counter + MOD * MOD) % MOD;
            counter++;
            continue;
        }
        final_answer += process_string(item.first, item.second, counter);
    }

    final_answer %= MODD;
    cout << (ll)final_answer << endl;

    return 0;
}
